/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/sonner.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
"use client";

import { CircleCheckIcon, InfoIcon, Loader2Icon, OctagonXIcon, TriangleAlertIcon } from "lucide-react";
import { useTheme } from "next-themes";
import { Toaster as Sonner } from "sonner";
import type { ToasterProps } from "sonner";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
const Toaster = ({
  ...props
}: ToasterProps & CapconsBasePropsLoose) => {
  const {
    theme = "system"
  } = useTheme();
  return <Sonner theme={theme as ToasterProps["theme"]} className="toaster group" icons={{
    success: <CircleCheckIcon className="size-4" />,
    info: <InfoIcon className="size-4" />,
    warning: <TriangleAlertIcon className="size-4" />,
    error: <OctagonXIcon className="size-4" />,
    loading: <Loader2Icon className="size-4 animate-spin" />
  }} style={{
    "--normal-bg": "var(--popover)",
    "--normal-text": "var(--popover-foreground)",
    "--normal-border": "var(--border)",
    "--border-radius": "var(--radius)"
  } as React.CSSProperties} {...capconsSpread(props)} />;
};
export { Toaster };
